"""界面本地化：简体中文、繁体中文、英语、韩语和日语。"""

LANGUAGES = [
    ("zh_CN", "简体中文"),
    ("zh_TW", "繁體中文"),
    ("en", "English"),
    ("ko", "한국어"),
    ("ja", "日本語"),
]

_LANGUAGE_NAMES = dict(LANGUAGES)
_current = "zh_CN"


def set_language(code: str) -> str:
    global _current
    _current = code if code in _LANGUAGE_NAMES else "zh_CN"
    return _current


def language() -> str:
    return _current


def language_options():
    return [(name, code) for code, name in LANGUAGES]


